sys_variable_value.value:
(function execute(inputs, outputs) {

    var text = inputs.raw_description || '';
    outputs.clean_description = text.replace(/\\/g, '\\\\')
                                    .replace(/"/g, '\\"')
                                    .replace(/\n/g, '\\n')
                                    .replace(/\r/g, '\\r');
})(inputs, outputs);

