sys_variable_value.value:
(function execute(inputs, outputs) {
    try {
        // 1. Parse the outer wrapper from the REST API
        var response = JSON.parse(inputs.raw_response);
        
        if (response.candidates && response.candidates.length > 0) {
            // 2. Get the actual text string Gemini generated
            var geminiText = response.candidates[0].content.parts[0].text;
            
            // 3. Clean up the text (strip the markdown ```json and ```)
            geminiText = geminiText.replace(/```json/gi, '').replace(/```/g, '').trim();
            
            // 4. SAFETY CHECK: If Gemini forgot the opening bracket, wrap it manually!
            if (!geminiText.startsWith("{")) {
                geminiText = "{" + geminiText + "}";
            }
            
            // 5. SAFETY CHECK: Forcefully extract only what is inside the curly brackets
            geminiText = geminiText.substring(geminiText.indexOf('{'), geminiText.lastIndexOf('}') + 1);
            
            // 6. Parse the cleaned inner string into a JSON object
            var aiData = JSON.parse(geminiText);
            
            // 7. Map directly to your Action Outputs
            outputs.short_description = aiData.short_description || "No description provided.";
            outputs.summary = aiData.summary || "No summary provided.";
            outputs.countermeasure = aiData.countermeasure || "None";
            outputs.malicious_intent_flag = aiData.malicious_intent_flag || "false";
        } else {
            outputs.summary = "API Error: No valid response returned.";
        }
    } catch (e) {
        outputs.summary = "Parse Error: " + e.message;
    }
})(inputs, outputs);

